  SORU_EKLE("traze.okuma",
    Q("traze.okuma", "uygulama", 2, "<i>Mahallemizdeki küçük kütüphane, hafta sonları çocuklarla dolup taşıyor. Kimi masalarda resimli kitaplara dalıyor, kimi köşede arkadaşına okuduğu hikâyeyi anlatıyor. Kütüphaneci Ayşe Hanım her gelen çocuğa yeni bir kitap öneriyor.</i><br><br>Bu metnin konusu nedir?", "Mahalle kütüphanesinde çocukların kitap okuması",
      [["Kitap okumak insanı mutlu eder.", "kavrama", "Bu bir yargı, yani ana fikir gibi bir cümle; konu ise metnin neyden söz ettiğidir."], ["Ayşe Hanım'ın mesleği", "dikkat", "Ayşe Hanım metinde geçiyor ama metin yalnızca onu anlatmıyor; bu bir ayrıntıdır."], ["Resimli kitapların yapılışı", "kavrama", "Metinde kitapların nasıl yapıldığından söz edilmiyor."]],
      "“Bu metin neyden söz ediyor?” diye sor; cevabın bütün cümleleri kapsasın.",
      ["🔎 Soruyu anlayalım: Metnin konusunu, yani neyden söz ettiğini bulacağız.",
       "💡 Hatırlayalım: Konu, metinde üzerinde durulan olay, durum ya da düşüncedir. Genellikle kısa bir söz öbeğiyle söylenir; ana fikir ise bir yargı bildirir.",
       "✏️ Uygulayalım: 1. cümle: Kütüphane çocuklarla dolu. 2. cümle: Çocuklar kitap okuyor, hikâye anlatıyor. 3. cümle: Kütüphaneci kitap öneriyor.",
       "✏️ Bütün cümleler aynı yerde, aynı etkinlikte birleşiyor: kütüphanede çocukların okuması.",
       "✅ Sonuç: Metnin konusu “Mahalle kütüphanesinde çocukların kitap okuması”dır.",
       "🔁 Kontrol edelim: Konuyu başlık gibi kısa düşün: “Kütüphanede Bir Hafta Sonu”. Bu başlık bütün metni kapsıyor."],
      { kural: "Konu “Metin neyden söz ediyor?”, ana fikir “Yazar ne demek istiyor?” sorusunun cevabıdır.", dogruNeden: "Metnin bütün cümleleri mahalle kütüphanesinde kitap okuyan çocukları anlatır." }),
    Q("traze.okuma", "aciklama", 2, "<i>Dedem her akşam yatmadan önce birkaç sayfa okur. “Gözlerim yorulsa da kitapsız uyuyamam.” der. Ondan öğrendim: Okumak bir alışkanlıktır ve her gün biraz yapıldıkça güçlenir. Şimdi ben de yatağımın başucunda bir kitapla uyuyorum.</i><br><br>Bu metne en uygun başlık hangisidir?", "Her Akşam Birkaç Sayfa",
      [["Dedemin Gözlükleri", "dikkat", "Metinde dedenin gözlerinin yorulduğundan söz ediliyor ama metin gözlükleri anlatmıyor."], ["Uyku Neden Önemlidir?", "kavrama", "Metin uykuyu değil, uyumadan önce okuma alışkanlığını anlatıyor."], ["Kütüphanede Bir Gün", "kavrama", "Metinde kütüphaneden hiç söz edilmiyor; olaylar evde geçiyor."]],
      "Başlık, metnin konusunu ya da ana fikrini kısaca yansıtmalı.",
      ["🔎 Soruyu anlayalım: Metnin bütününü kapsayan, kısa ve dikkat çekici bir başlık seçeceğiz.",
       "💡 Hatırlayalım: İyi bir başlık metnin konusunu ya da ana fikrini yansıtır; bir ayrıntıyı değil.",
       "✏️ Uygulayalım: Metnin ana fikri: Okumak bir alışkanlıktır, her gün biraz yapıldıkça güçlenir.",
       "✏️ Hem dede hem de anlatıcı her akşam yatmadan önce okuyor. “Her Akşam Birkaç Sayfa” bu düzenli okumayı anlatır.",
       "✅ Sonuç: En uygun başlık “Her Akşam Birkaç Sayfa”dır.",
       "🔁 Kontrol edelim: Bu başlığı okuyan biri, metnin her gün düzenli okumayı anlattığını hemen tahmin eder."],
      { kural: "Başlık, metnin konusunu ya da ana fikrini kısaca yansıtır.", dogruNeden: "Metin her akşam düzenli okumanın alışkanlık hâline gelmesini anlatır; başlık da bunu yansıtır." }),
    () => {
      const gun = OGR.sec([10, 12, 15, 20, 25]);
      const sure = OGR.R(6, 14);
      const sayfa = gun * sure;
      const ad = OGR.sec(["Elif", "Mert", "Zeynep", "Kerem", "Defne"]);
      return S({
        kaz: "traze.okuma", duzey: "transfer", zorluk: 2,
        soru: `${ad}, okuma alışkanlığı kazanmak için her gün <b>${gun} sayfa</b> kitap okumaya karar verdi. Okuduğu Azerbaycan masalları kitabı <b>${sayfa} sayfa</b>dır. ${ad} bu kitabı kaç günde bitirir?`,
        dogru: sure + " gün",
        yanlis: [[(sayfa - gun) + " gün", "islem", "Kitabın sayfa sayısından günlük sayfayı çıkardın; oysa kaç kez sığdığını bulmak için bölmen gerekir."], [(sure + 1) + " gün", "islem", `Bölmede bir fazla saydın; ${gun} × ${sure + 1} = ${gun * (sure + 1)} eder, bu da kitaptan fazla.`], [(sayfa + gun) + " gün", "strateji", "Sayıları topladın; ama bir bütünü eşit parçalara ayırırken bölme yapılır."]],
        ipucu: `Kitabı her gün ${gun} sayfalık parçalara ayır. Kaç parça olur?`,
        cozum: [
          `🔎 Soruyu anlayalım: Kitap ${sayfa} sayfa, ${ad} her gün ${gun} sayfa okuyor. Kaç gün gerektiğini bulacağız.`,
          "💡 Hatırlayalım: Bir bütünü eşit parçalara ayırıp kaç parça olduğunu bulmak için bölme yaparız.",
          `✏️ Uygulayalım: Toplam sayfa ÷ günlük sayfa = gün sayısı → ${sayfa} ÷ ${gun}`,
          `✏️ ${sayfa} ÷ ${gun} = ${sure}`,
          `✅ Sonuç: ${ad} kitabı ${sure} günde bitirir.`,
          `🔁 Kontrol edelim: ${sure} gün × ${gun} sayfa = ${sayfa} sayfa. Kitabın tamamı okunmuş! Her gün biraz okumak, büyük kitapları bile bitirmeni sağlar.`,
        ],
        kural: "Okuma planı: toplam sayfa ÷ günlük sayfa = gün sayısı.",
        dogruNeden: `${sayfa} ÷ ${gun} = ${sure}; her gün ${gun} sayfa okuyan ${ad} kitabı ${sure} günde bitirir.`,
      });
    },
  );

